  border-radius: 6px;
  cursor: pointer;
  font-size: 15px;
  margin-top: 6px;
}

.btn-add:disabled { background-color: #a1a1aa; cursor: not-allowed; }

.btn-plain {
  background: none;
  border: 1px solid #d4d4d8;
  border-radius: 6px;
  padding: 4px 10px;
  cursor: pointer;
  font-size: 14px;
  margin-right: 6px;
}

.btn-danger {
  background-color: #b91c1c;
  color: #ffffff;
  border: none;
  border-radius: 6px;
  padding: 4px 10px;
  cursor: pointer;
  font-size: 14px;
  margin-right: 6px;
}

.error {
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 10px;
  color: #991b1b;
  padding: 12px 14px;
  margin: 12px 0;
}

.error p { margin: 0 0 8px; }

// Shop.mn-ий админ API — дуураймал сервер. Энэ файлыг өөрчлөх шаардлагагүй.
//
// Бүх хүсэлт "Authorization: Bearer <token>" толгой шаардана. Токенгүй бол 401.

(function () {
  const TOKEN = "admin-token-2026";

  let products = [
    { id: 1, name: "Монгол дээл", price: 129000, stock: 4 },
    { id: 2, name: "Малгай", price: 45000, stock: 12 },
    { id: 3, name: "Гутал", price: 89000, stock: 0 },
  ];

  let nextId = 4;
  const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  function json(body, status) {
    return new Response(body === null ? "" : JSON.stringify(body), {
      status: status || 200,
      headers: { "Content-Type": "application/json" },
    });
  }

  function authorised(options) {
    const headers = (options && options.headers) || {};
    const header = headers.Authorization || headers.authorization || "";
    return header === "Bearer " + TOKEN;
  }

  window.ADMIN_TOKEN = TOKEN;

  window.fetch = async function (url, options) {
    const method = ((options && options.method) || "GET").toUpperCase();
    const path = String(url);
    await wait(60);

    if (window.API_SHOULD_FAIL) return json({ error: "Серверт алдаа гарлаа" }, 500);

    if (!authorised(options)) {
      return json({ error: "Нэвтрэх шаардлагатай" }, 401);
    }

    if (path.endsWith("/api/admin/products") && method === "GET") {
      return json(window.API_EMPTY ? [] : products);
    }

    if (path.endsWith("/api/admin/products") && method === "POST") {
      const input = JSON.parse(options.body);

      if (!input.name || String(input.name).trim().length < 2) {
        return json({ error: "Барааны нэр 2-оос урт байх ёстой" }, 400);
      }
      if (!Number.isFinite(input.price) || input.price <= 0) {
        return json({ error: "Үнэ эерэг тоо байх ёстой" }, 400);
      }

      const created = { id: nextId++, name: input.name, price: input.price, stock: 0 };
      products.push(created);
      return json(created, 201);
    }

    const remove = path.match(/\/api\/admin\/products\/(\d+)$/);
    if (remove && method === "DELETE") {
      const id = Number(remove[1]);
      if (!products.some((p) => p.id === id)) {
        return json({ error: "Бараа олдсонгүй" }, 404);
      }
      products = products.filter((p) => p.id !== id);
      return json(null, 204);
    }

    return json({ error: "Хаяг олдсонгүй: " + path }, 404);
  };
})();

import React, { useEffect, useState } from "react";
import { createRoot } from "react-dom/client";

const API = "/api/admin/products";

function formatPrice(value) {
  return "₮ " + value.toLocaleString("en-US");
}

// Хүсэлт бүрд токен явуулах ганц газар.
function authHeaders(extra) {
  return { Authorization: "Bearer " + window.ADMIN_TOKEN, ...extra };
}

function App() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [name, setName] = useState("");
  const [priceInput, setPriceInput] = useState("");
  const [formError, setFormError] = useState(null);
  const [saving, setSaving] = useState(false);

  const ready = !loading && !error;

  async function loadProducts() {
    setError(null);
    setLoading(true);

    try {
      const response = await fetch(API, { headers: authHeaders() });
      if (!response.ok) {
        throw new Error("Бараануудыг ачаалж чадсангүй (" + response.status + ")");
      }
      setProducts(await response.json());
    } catch (problem) {
      setError(problem.message);
    } finally {
      setLoading(false);
    }
  }

  // энд бичнэ үү

  useEffect(() => {
    loadProducts();
  }, []);

  return (
    <main>
      <header className="topbar">
        <h1>Shop.mn — админ</h1>
        <button className="btn-plain" data-testid="refresh" onClick={loadProducts} disabled={loading}>
          Шинэчлэх
        </button>
      </header>

      {loading ? <p data-testid="loading">Ачаалж байна…</p> : null}

      {error ? (
        <div className="error" data-testid="error" role="alert">
          <p>{error}</p>
          <button className="btn-plain" data-testid="retry" onClick={loadProducts}>Дахин оролдох</button>
        </div>
      ) : null}

      {ready && products.length === 0 ? (
        <p data-testid="empty">Одоогоор бараа алга байна.</p>
      ) : null}

      {!loading && products.length > 0 ? (
        <table data-testid="table">
          <caption>Shop.mn-ий бараанууд</caption>
          <thead>
            <tr>
              <th scope="col">Нэр</th>
              <th scope="col">Үнэ</th>
              <th scope="col">Үлдэгдэл</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.id} data-testid="row">
                <td>{product.name}</td>
                <td>{formatPrice(product.price)}</td>
                <td>{product.stock}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : null}


      {/* энд бичнэ үү */}


      <form className="new-product" data-testid="form">
        <h2>Шинэ бараа</h2>

        <label htmlFor="p-name">Нэр</label>
        <input
          id="p-name"
          name="name"
          data-testid="f-name"
        />

        <label htmlFor="p-price">Үнэ (₮)</label>
        <input
          id="p-price"
          name="price"
          type="number"
          data-testid="f-price"
        />

        {formError ? (
          <p className="error" data-testid="form-error" role="alert">{formError}</p>
        ) : null}

        <button type="submit" className="btn-add" data-testid="save">
          {saving ? "Хадгалж байна…" : "Нэмэх"}
        </button>
      </form>
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);

import React, { useEffect, useState } from "react";
import { createRoot } from "react-dom/client";

const API = "/api/admin/products";

function formatPrice(value) {
  return "₮ " + value.toLocaleString("en-US");
}

// Хүсэлт бүрд токен явуулах ганц газар.
function authHeaders(extra) {
  return { Authorization: "Bearer " + window.ADMIN_TOKEN, ...extra };
}

function App() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [name, setName] = useState("");
  const [priceInput, setPriceInput] = useState("");
  const [formError, setFormError] = useState(null);
  const [saving, setSaving] = useState(false);

  const ready = !loading && !error;

  async function loadProducts() {
    setError(null);
    setLoading(true);

    try {
      const response = await fetch(API, { headers: authHeaders() });
      if (!response.ok) {
        throw new Error("Бараануудыг ачаалж чадсангүй (" + response.status + ")");
      }
      setProducts(await response.json());
    } catch (problem) {
      setError(problem.message);
    } finally {
      setLoading(false);
    }
  }

  async function createProduct(event) {
    event.preventDefault();

    const price = Number(priceInput);
    if (name.trim().length < 2 || !Number.isFinite(price) || price <= 0) {
      setFormError("Нэр 2-оос урт, үнэ эерэг тоо байх ёстой.");
      return;
    }

    setFormError(null);
    setSaving(true);

    try {
      const response = await fetch(API, {
        method: "POST",
        headers: authHeaders({ "Content-Type": "application/json" }),
        body: JSON.stringify({ name: name.trim(), price: price }),
      });

      if (!response.ok) {
        const body = await response.json();
        throw new Error(body.error || "Хадгалж чадсангүй");
      }

      setName("");
      setPriceInput("");
      await loadProducts();
    } catch (problem) {
      setFormError(problem.message);
    } finally {
      setSaving(false);
    }
  }

  useEffect(() => {
    loadProducts();
  }, []);

  return (
    <main>
      <header className="topbar">
        <h1>Shop.mn — админ</h1>
        <button className="btn-plain" data-testid="refresh" onClick={loadProducts} disabled={loading}>
          Шинэчлэх
        </button>
      </header>

      {loading ? <p data-testid="loading">Ачаалж байна…</p> : null}

      {error ? (
        <div className="error" data-testid="error" role="alert">
          <p>{error}</p>
          <button className="btn-plain" data-testid="retry" onClick={loadProducts}>Дахин оролдох</button>
        </div>
      ) : null}

      {ready && products.length === 0 ? (
        <p data-testid="empty">Одоогоор бараа алга байна.</p>
      ) : null}

      {!loading && products.length > 0 ? (
        <table data-testid="table">
          <caption>Shop.mn-ий бараанууд</caption>
          <thead>
            <tr>
              <th scope="col">Нэр</th>
              <th scope="col">Үнэ</th>
              <th scope="col">Үлдэгдэл</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.id} data-testid="row">
                <td>{product.name}</td>
                <td>{formatPrice(product.price)}</td>
                <td>{product.stock}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : null}


      <form className="new-product" data-testid="form" onSubmit={createProduct}>
        <h2>Шинэ бараа</h2>

        <label htmlFor="p-name">Нэр</label>
        <input
          id="p-name"
          name="name"
          data-testid="f-name"
          value={name}
          onChange={(event) => setName(event.target.value)}
        />

        <label htmlFor="p-price">Үнэ (₮)</label>
        <input
          id="p-price"
          name="price"
          type="number"
          data-testid="f-price"
          value={priceInput}
          onChange={(event) => setPriceInput(event.target.value)}
        />

        {formError ? (
          <p className="error" data-testid="form-error" role="alert">{formError}</p>
        ) : null}

        <button type="submit" className="btn-add" data-testid="save" disabled={saving}>
          {saving ? "Хадгалж байна…" : "Нэмэх"}
        </button>
      </form>
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);
